-- Omgång 8 (2026-11-10): de sista platserna utan källor. Bara fakta, egna formuleringar.
begin;

-- 1. Handelshuset Stärkan blir Reunion Kivik (samma hus, samma kartnål och öppettider)
update public.places set name = 'Reunion Kivik', website_url = 'https://www.reunionhome.se/pages/reunionkivik', phone = '072-225 72 20' where id = 284;

-- 2. Nya beskrivningar (17 platser)
update public.places set short_description = 'Sandstensklippor från urtiden vid havet', description = 'Vid Vårhallen i Tobisvik, strax utanför Simrishamn, går flata klippor av sandsten rakt ut i Östersjön. Sandstenen bildades på havsbotten under kambrium, för ungefär en halv miljard år sedan, och lagren ligger i tydliga skikt. Titta noga så ser du fossil och böljmärken i berget, alltså spår efter vågor från en tid långt innan dinosaurierna. Platsen är som mest storslagen när det blåser och vågorna slår mot klipporna. Det finns parkering och informationsskyltar, och Prästens badkar ligger en bit norrut.' where id = 31; -- Vårhallen - Tobisvik
update public.places set short_description = 'Kluven jättesten med gamla sägner', description = 'Klövasten är ett stort, kluvet flyttblock strax söder om Glemmingebro, alldeles intill vägen mot Ystad. Stenen är ett så kallat jättekast, och enligt folktron slungades den av en jättekvinna på Bornholm som ville träffa Glemminge kyrka, men kastet blev för kort och stenen sprack när den landade. Kring stenen finns flera andra sägner, bland annat att halvorna går ihop när de känner doft av nybakat bröd. Vid stenen står en skylt som berättar mer. Lätt att stanna till vid på väg genom bygden.' where id = 40; -- Klövasten
update public.places set short_description = 'Skogssjö med badplats och stig runt', description = 'Gyllebosjön är en liten sjö omgiven av bokskog på norra Österlen. Sjön och skogen runt omkring är naturreservat. En stig på cirka fyra kilometer går runt hela sjön, och vid den östra stranden finns en badplats. Här kan man också hyra roddbåt och köpa fiskekort. På en udde vid sjöns södra sida ligger Gyllebo slott.' where id = 170; -- Gyllebosjön
update public.places set short_description = 'Holländarkvarn från 1825 med kopparhätta', description = 'Hagestadborgs mölla är en holländare, alltså en väderkvarn där bara toppen vrids mot vinden. Den byggdes 1825 och har en kupolformad hätta täckt med kopparplåt, och vingarna spänner över drygt 20 meter. Kvarnen har lagats och rustats upp genom åren men aldrig moderniserats, och den siste mjölnaren slutade mala på 1950-talet. I dag ägs den av Ystads kommun och sköts av byalaget i Hagestad. Gården intill är privat, så titta från vägen. På Skånska möllornas dag i juli brukar kvarnen vara öppen för besök.' where id = 213; -- Hagestadborgs mölla
update public.places set short_description = 'Gravfält från bronsåldern vid kustvägen', description = 'Lunnabjär gravfält ligger vid kustvägen mellan Nybostrand och Örnahusen. Gravarna kom fram 1934, när den nya kustvägen skulle byggas, och består av högar, rösen och brandgravar från bronsåldern. Medan arkeologerna från Lund väntade på bättre väder tog bygdens folk saken i egna händer och flyttade gravarna, sten för sten, bort från vägbygget. Det man ser i dag är alltså deras återuppbyggnad. Det finns parkering och en informationsskylt, så det är ett enkelt stopp på vägen längs sydkusten.' where id = 214; -- Lunnabjär gravfält
update public.places set short_description = 'Välbevarad kalkugn från 1862', description = 'Kalkugnen i Östra Tommarp byggdes 1862 och ligger knappt en kilometer sydväst om kyrkan. Här brändes kalksten till kalk: stenen staplades för hand i ugnen, öppningarna murades igen och sedan eldade man under stenen i ungefär en vecka. Den sista bränningen gjordes 1907, och sedan 1968 ägs ugnen av kommunen, som bevarar den. Det är en av de bäst bevarade kalkugnarna i Skåne. Östra Tommarp var under medeltiden en stad med kloster och egen myntprägling. Vid ugnen finns parkering och en informationstavla.' where id = 219; -- Östra Tommarps Kalkugn 
update public.places set short_description = 'Gånggrift från stenåldern på slätten', description = 'Tågarpsdösen ligger ute på slätten nära Östra Tommarp. Trots namnet är den inte en dös utan en gånggrift, en stenkammargrav från stenåldern som användes i flera hundra år. Graven grävdes ut 1970, och jordhögen som täcker den har sedan återställts. Högen är omkring 15 meter bred, och på ett av takblocken finns 22 skålgropar, troligen gjorda under bronsåldern. Graven ligger på åkermark, så det kan vara svårt att komma nära under delar av året. Den syns dock bra från vägen.' where id = 220; -- Tågarpsdösen 
update public.places set short_description = 'Stor boll som markerar Österlens mittpunkt', description = 'Österlen är ingen officiell region, och var gränserna går har länge diskuterats. På 1920-talet ritade Fritiof Nilsson Piraten och två andra kända österlenare upp en gräns, och räknar man efter den hamnar mittpunkten i Smedstorp. Byn har kallat sig Österlens mittpunkt sedan 1950-talet, och 2008 ställdes en stor boll av glasfiber upp vid järnvägsstationen som symbol. Bollen är lätt att hitta, och det finns parkering alldeles intill. Ett roligt stopp för en bild när man ändå passerar Smedstorp.' where id = 221; -- Österlens Mittpunkt 
update public.places set short_description = 'Holländarkvarn från 1887 som fortfarande mal', description = 'Övraby väderkvarn står synlig på slätten söder om Tomelilla. Kvarnen byggdes 1887 av kvarnbyggaren Anders Östberg och är en holländare, där hättan vrids efter vinden. Både byggnaden och maskineriet har kvar sin gamla karaktär, och kvarnen fungerar fortfarande. Bredvid ligger mjölnarbostaden, en vitputsad skånelänga från samma tid. Den siste mjölnaren malde med vindkraft ända till 1974, och sedan dess sköts kvarnen av Föreningen Övraby Mölla. Vid särskilda mölledagar mals och säljs mjöl på plats.' where id = 222; -- Övraby väderkvarn 
update public.places set short_description = 'Rester av en skeppssättning på Gårdlösaåsen', description = 'Alnabjär ligger vid riksväg 11 på Gårdlösaåsen, där människor bodde under hela järnåldern. Av skeppssättningen här finns fyra stora stenar kvar, och de syns långt ut i landskapet. Runt omkring finns flera små stensättningar som nästan inte märks i terrängen. Enligt sägnen är det kung Alnes grav. Inte långt härifrån gjordes ett känt gravfynd med ett dräktspänne i silver, som har en av Sveriges äldsta runinskrifter. Marken brukas, så visa hänsyn. Det finns ingen parkering, men en ficka vid riksvägen en bit bort.' where id = 223; -- Alnabjär Skeppssättning
update public.places set short_description = 'Två skeppssättningar och en domarring', description = 'På Gårdlösaåsen finns ett fornlämningsområde med två skeppssättningar och en domarring. Den större skeppssättningen består av 15 stenar och den mindre av 16, med en sten i mitten. Skeppssättningar är gravar där stenarna är resta i formen av ett skepp, och en domarring är en ring av resta stenar. Åsen var bebodd under hela järnåldern, och i trakten finns flera andra gravar och boplatser från samma tid. Visa hänsyn om marken runt omkring brukas.' where id = 224; -- Gårdlösa Skeppssättning
update public.places set short_description = 'Ensamt träd och populärt fotomotiv', description = 'Ett ensamt träd som står fritt i landskapet vid Baskemölla, med havet i närheten. Platsen har blivit ett omtyckt fotomotiv, särskilt i soluppgång och skymning. Visa hänsyn om marken runt omkring brukas.' where id = 226; -- Lonely Tree Baskemölla 
update public.places set short_description = 'Ekologisk gårdsbutik i Bästekille', description = 'Bertil''son är en ekologisk gårdsbutik i Bästekille, i fruktbygden mellan Kivik och Sankt Olof. Ett bra stopp för den som vill handla ekologiskt direkt från gården.' where id = 265; -- Bertil'son i Bästekille
update public.places set short_description = 'Kläder, inredning och outlet i Kivik', description = 'Reunion Kivik är en butik i Handelshuset Stärkan på Kiviks stora väg. Här finns kläder och inredning, nya kollektioner och en outletavdelning med fynd. Reunion har funnits på Österlen tidigare, på en gård i Hagestad, och är nu tillbaka med en egen butik i Kivik. I samma hus ligger Sally på Kivik med fika, mat och surdegspizza, så det är lätt att kombinera shopping med en paus.' where id = 284; -- Handelshuset Stärkan → Reunion Kivik
update public.places set short_description = 'Konstgalleri nära Glemmingebro', description = 'Kabusa Art Gallery är ett galleri som visar och säljer konst av flera olika konstnärer. Ny konst kommer in löpande, och det som finns att se läggs upp på galleriets hemsida. Kom förbi och botanisera, kanske hittar du något nytt.' where id = 310; -- Kabusa Art Gallery
update public.places set short_description = 'Semesterlägenhet med trädgård på södra Österlen', description = 'Knappagården är en semesterlägenhet på södra Österlen, inte långt från Kåseberga. Lägenheten har två sovrum, vardagsrum, ett fullt utrustat kök och badrum med dusch. Utanför finns en uteplats och en trädgård med grill, och parkering och wifi ingår.' where id = 333; -- Knappagården
update public.places set short_description = 'Bed and breakfast med bastu och bubbelbad', description = 'Wisteria Österlen är ett bed and breakfast några kilometer från Glimmingehus på södra Österlen. Alla rum har eget badrum, luftkonditionering och egen terrass. Här finns också bastu och bubbelbad, och från trädgården kan man koppla av med utsikt. Frukosten serveras som buffé, och det finns även vegetariskt alternativ. Härifrån är det nära till Simrishamn och lagom avstånd till Sandhammaren, Kåseberga och Ales stenar. Trakten passar bra att cykla i. Parkering och wifi ingår.' where id = 342; -- Wisteria Österlen

-- 3. Quadambra Park tar inte emot bokningar längre
